-- 118_ficha_producao_saude_estoque_comprados_kits.sql
-- Ficha do Gerenciamento de Produção: Saúde do Estoque com Coloração, Apoio e componentes de kit. Aditiva e idempotente.

UPDATE mapa_modules SET
    detail = jsonb_set(detail, '{attention}', COALESCE(detail->'attention', '[]'::jsonb) || to_jsonb('Saúde do Estoque agora cobre também Coloração e Apoio (comprados prontos) e não existe mais tela antiga. Comprados: estoque + pedido de compra em trânsito − pedidos de venda, média e ideal da Demanda (a mesma base da sugestão de compra do Compras); Baixo = o Compras sugere comprar; no lugar de em produção mostra o trânsito e a previsão de chegada mais próxima (purchase_orders.d_previsao). Quem é componente de kit (kit_composicao) é julgado pela venda direta mais a dos kits × a quantidade no kit: média, cobertura, vendas de 3 e 12 meses, última venda e ideal (o ideal do produto mais o de cada kit × quantidade); selo Só kit ou Também em kit e, na linha, quanto da venda veio direto e por kits. Cartões no topo são exceção do Edson à regra sem KPI, só nesta tela'::text)),
    updated_at = NOW()
WHERE module_key = 'producao'
  AND NOT (COALESCE(detail->'attention', '[]'::jsonb) @> to_jsonb('Saúde do Estoque agora cobre também Coloração e Apoio (comprados prontos) e não existe mais tela antiga. Comprados: estoque + pedido de compra em trânsito − pedidos de venda, média e ideal da Demanda (a mesma base da sugestão de compra do Compras); Baixo = o Compras sugere comprar; no lugar de em produção mostra o trânsito e a previsão de chegada mais próxima (purchase_orders.d_previsao). Quem é componente de kit (kit_composicao) é julgado pela venda direta mais a dos kits × a quantidade no kit: média, cobertura, vendas de 3 e 12 meses, última venda e ideal (o ideal do produto mais o de cada kit × quantidade); selo Só kit ou Também em kit e, na linha, quanto da venda veio direto e por kits. Cartões no topo são exceção do Edson à regra sem KPI, só nesta tela'::text));
